package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;
/** Verified own-model checkpoints, pointers and rollback. Weights never execute code. */
final class ModelDepot{
 static final String CHAT="chat34/chat34.bin",PIXEL="pixel-v2/character21.bin";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-model-training",0);}
 static String asset(String kind){if(kind.equals("chat"))return CHAT;if(kind.equals("pixel"))return PIXEL;throw new IllegalArgumentException("Modelo desconocido.");}
 static JSONObject row(Context c,String kind)throws Exception{return new JSONObject(prefs(c).getString(kind,"{}"));}
 static File verified(Context c,String kind)throws Exception{JSONObject row=row(c,kind);if(!row.has("path"))return null;File f=new File(row.getString("path"));if(!f.getCanonicalPath().startsWith(c.getDir("model-training",0).getCanonicalPath()+File.separator)||f.canWrite()||!ProjectRuntime.digest(f).equals(row.getString("sha256")))throw new IOException("El checkpoint cambió.");return f;}
 static InputStream open(Context c,String kind)throws Exception{File file=verified(c,kind);return file==null?c.getAssets().open(asset(kind)):new FileInputStream(file);}
 static String revision(Context c,String kind){return prefs(c).getString(kind,"base");}
 static boolean active(Context c,String kind){return prefs(c).contains(kind);}
 static File save(Context c,String kind,byte[] bytes)throws Exception{File f=new File(c.getDir("model-training",0),kind+"-"+UUID.randomUUID()+".bin");OnDeviceJava.immutable(f,bytes);return f;}
 static synchronized void publish(Context c,String kind,File file,JSONObject report,String before)throws Exception{publish(c,kind,file,report,before,null);}
 static synchronized void publish(Context c,String kind,File file,JSONObject report,String before,JSONArray preview)throws Exception{if(!revision(c,kind).equals(before))throw new IOException("El modelo cambió durante el entrenamiento.");String backup=prefs(c).getString(kind,"");if(backup.isEmpty()){File snapshot;try(InputStream in=c.getAssets().open(asset(kind))){snapshot=save(c,kind,OnDeviceJava.bytes(in,8000000));}JSONObject prior=report(c,kind);if(prior==null)prior=new JSONObject().put("baseline",true).put("kind",kind);JSONObject saved=new JSONObject().put("path",snapshot.getAbsolutePath()).put("sha256",ProjectRuntime.digest(snapshot)).put("report",prior).put("baseAsset",asset(kind));JSONArray oldPreview=preview(c,kind);if(oldPreview!=null)saved.put("preview",oldPreview);backup=saved.toString();}JSONObject row=new JSONObject().put("path",file.getAbsolutePath()).put("sha256",ProjectRuntime.digest(file)).put("report",report).put("baseAsset",asset(kind));if(preview!=null){if(preview.length()!=1024)throw new IOException("Vista previa inválida.");for(int i=0;i<preview.length();i++){double v=preview.getDouble(i);if(Double.isNaN(v)||Double.isInfinite(v)||Math.abs(v)>30)throw new IOException("Delta de vista previa inválido.");}row.put("preview",preview);}if(!prefs(c).edit().putString(kind+"Backup",backup).putString(kind,row.toString()).putString(kind+"Report",report.toString()).commit())throw new IOException("No pude activar el checkpoint.");if(kind.equals("pixel"))NeuralSprites.resetModels();}
 static synchronized String undo(Context c,String kind)throws Exception{if(!prefs(c).contains(kind+"Backup"))return "No hay pesos anteriores guardados de "+kind+".";String old=prefs(c).getString(kind+"Backup","");if(!old.isEmpty()){JSONObject row=new JSONObject(old);File f=new File(row.getString("path"));if(!ProjectRuntime.digest(f).equals(row.getString("sha256")))throw new IOException("El checkpoint anterior cambió.");}SharedPreferences.Editor edit=prefs(c).edit().remove(kind+"Backup");if(old.isEmpty())edit.remove(kind);else edit.putString(kind,old);if(!edit.commit())throw new IOException("No pude recuperar los pesos.");if(kind.equals("pixel"))NeuralSprites.resetModels();return "Recuperé los pesos anteriores de "+kind+".";}
 static JSONObject embedded(Context c)throws Exception{try{return new JSONObject(AppJavaChat.asset(c,"training/baked-models.json",80000));}catch(FileNotFoundException missing){return new JSONObject().put("version",1).put("models",new JSONObject());}}
 static JSONObject report(Context c,String kind)throws Exception{if(active(c,kind))return row(c,kind).getJSONObject("report");JSONObject all=embedded(c).getJSONObject("models");return all.has(kind)?all.getJSONObject(kind).getJSONObject("report"):null;}
 static JSONArray preview(Context c,String kind)throws Exception{if(active(c,kind))return row(c,kind).optJSONArray("preview");JSONObject models=embedded(c).getJSONObject("models");return models.has(kind)?models.getJSONObject(kind).optJSONArray("preview"):null;}
 static boolean tuned(Context c,String kind)throws Exception{JSONObject report=report(c,kind);return report!=null&&report.has("type")&&report.optBoolean("accepted",false);}
 static Map<String,byte[]> baked(Context c)throws Exception{Map<String,byte[]> out=new LinkedHashMap<>();JSONObject meta=embedded(c),models=meta.getJSONObject("models");for(String kind:new String[]{"chat","pixel"}){File f=verified(c,kind);if(f!=null)try(InputStream in=new FileInputStream(f)){out.put("assets/"+asset(kind),OnDeviceJava.bytes(in,8000000));models.put(kind,new JSONObject().put("sha256",row(c,kind).getString("sha256")).put("report",row(c,kind).getJSONObject("report")));JSONArray preview=preview(c,kind);if(preview!=null)models.getJSONObject(kind).put("preview",preview);}}if(models.length()>0)out.put("assets/training/baked-models.json",meta.toString().getBytes("UTF-8"));return out;}
}
